await p.click('#gen');
let key=null;
for (let i=0;i<50;i++){
  await p.waitForTimeout(100);
  const t = await p.textContent('#toast');
  const h = await p.getAttribute('#toast','hidden');
  if (h===null && t.trim()) { key=t.trim(); console.log('TOAST:', JSON.stringify(t)); break; }
}
console.log('KEY=',key);
await p.goto('http://127.0.0.1:54569/webhooks');
console.log((await p.content()).match(/<main[\s\S]*<\/main>/)?.[0]);
await b.close();
EOF
